//! Configuration file discovery and loading.
//!
//! This module handles finding and loading configuration files from
//! various locations in the correct priority order. Both YAML
//! (`.yml`/`.yaml`) and TOML (`.toml`) formats are supported.

use crate::config::extends::ExtendsResolver;
use crate::config::merger::merge_configs;
use crate::config::schema::BivvyConfig;
use crate::error::{BivvyError, Result};
use std::fs;
use std::path::{Path, PathBuf};

/// Supported configuration file formats.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ConfigFormat {
    /// YAML format (.yml or .yaml)
    Yaml,
    /// TOML format (.toml)
    Toml,
}

impl ConfigFormat {
    /// Detect the configuration format from a file path's extension.
    ///
    /// Returns `Yaml` for `.yml`/`.yaml` extensions and `Toml` for `.toml`.
    /// Defaults to `Yaml` for unrecognized extensions.
    pub fn from_path(path: &Path) -> Self {
        match path.extension().and_then(|e| e.to_str()) {
            Some("toml") => ConfigFormat::Toml,
            _ => ConfigFormat::Yaml,
        }
    }
}

/// Convert a `toml::Value` into a `serde_yaml::Value`.
///
/// This bridges TOML-parsed data into the YAML-based merge pipeline
/// so that TOML and YAML configs can be merged together seamlessly.
pub fn toml_to_yaml_value(toml_val: &toml::Value) -> serde_yaml::Value {
    match toml_val {
        toml::Value::String(s) => serde_yaml::Value::String(s.clone()),
        toml::Value::Integer(i) => serde_yaml::Value::Number(serde_yaml::Number::from(*i)),
        toml::Value::Float(f) => {
            serde_yaml::Value::Number(serde_yaml::Number::from(*f))
        }
        toml::Value::Boolean(b) => serde_yaml::Value::Bool(*b),
        toml::Value::Datetime(dt) => serde_yaml::Value::String(dt.to_string()),
        toml::Value::Array(arr) => {
            serde_yaml::Value::Sequence(arr.iter().map(toml_to_yaml_value).collect())
        }
        toml::Value::Table(table) => {
            let mut map = serde_yaml::Mapping::new();
            for (k, v) in table {
                map.insert(
                    serde_yaml::Value::String(k.clone()),
                    toml_to_yaml_value(v),
                );
            }
            serde_yaml::Value::Mapping(map)
        }
    }
}

